fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    // Helper function to compute S(k) as defined
    fn prefix_sum(k: i8) -> i8 {
        if k % 2 == 0 {
            k / 2
        } else {
            -(k + 1) / 2
        }
    }
    
    queries
        .into_iter()
        .map(|(l, r)| {
            // Compute S(r) - S(l - 1)
            // Note: l >= 1 per problem statement, so l-1 is safe
            prefix_sum(r) - prefix_sum(l - 1)
        })
        .collect()
}